package local.pocketchat;
import java.util.*;
import org.mozilla.geckoview.*;
import android.net.Uri;
import org.json.JSONObject;
public final class Overview46Host {
  static int checks;static void check(boolean value,String name){checks++;if(!value)throw new AssertionError(name);}
  static final class Listener implements GeckoWebView.ExitIpPageListener{int updates,closes;String message="";public void changed(String value){updates++;message=value;}public void closed(){closes++;}}
  static GeckoWebView fresh(){ProfileCatalog.row=new JSONObject().put("created",true).put("environmentId","environment-A").put("generation",3);ChatSession s=new ChatSession();GeckoWebView web=new GeckoWebView(s);ChatSession.instance=s;return web;}
  static void reject(String label,java.util.function.Consumer<GeckoWebView> change){GeckoWebView web=fresh();change.accept(web);GeckoSession original=web.current;Listener listener=new Listener();check(!web.openExitIpPage(listener).isEmpty(),label+" rejects opening");check(web.current==original&&!web.hasExitIpPage()&&original.loads==0,label+" preserves original");}
  static void retire(String label,java.util.function.Consumer<GeckoWebView> change){GeckoWebView web=fresh();Listener listener=new Listener();GeckoSession original=web.current;Object port=web.ports.get(original);check(web.openExitIpPage(listener).isEmpty(),label+" starts");ExitIpPageSession page=web.exitIpPage;change.accept(web);page.aux.navigation.onLoadError(page.aux,ExitIpPageSession.URL,new WebRequestError());check(listener.updates==0,label+" suppresses stale callback");page.watch.run();check(!web.hasExitIpPage()&&listener.closes==1&&!page.aux.isOpen(),label+" closes own auxiliary");check(web.current==original&&web.ports.get(original)==port&&original.loads==0,label+" keeps original session and port");page.message("late");check(listener.updates==0,label+" retired callback stays silent");}
  public static void main(String[] args)throws Exception{
    EnvironmentOverviewState state=new EnvironmentOverviewState("nonce","environment-A",0,3);
    check(state.remaining(100000)==5000&&!state.expired(100000),"no deadline before first visible");state.visible(100000);state.visible(104000);
    check(state.visibleAt==100000&&state.remaining(104999)==1&&!state.expired(104999),"repeated visibility cannot restart five seconds");check(state.expired(105000)&&state.remaining(105001)==0,"exact monotonic deadline expires");
    EnvironmentOverviewState skipped=new EnvironmentOverviewState("nonce","environment-A",0,3);skipped.close();skipped.visible(10);check(skipped.remaining(10)==0&&skipped.visibleAt==-1,"skip closes even before visible");
    check(state.matches("environment-A",0,3)&&!state.matches("environment-B",0,3)&&!state.matches("environment-A",1,3)&&!state.matches("environment-A",0,4),"environment identity is exact");
    for(String bad:new String[]{"http://ip123.in/zh/","https://ip123.in.evil/zh/","https://user@ip123.in/zh/","https://ip123.in:444/zh/","https://127.0.0.1/","intent://ip123.in/zh/"})check(!ExitIpPageSession.target(bad),"reject URL "+bad);
    check(ExitIpPageSession.target(ExitIpPageSession.URL)&&ExitIpPageSession.target("https://ip123.in:443/zh/"),"exact HTTPS IP123 target");
    GeckoWebView web=fresh();GeckoSession original=web.current;Object port=web.ports.get(original);Listener listener=new Listener();long epoch=web.owner.navigationEpoch;
    check(web.openExitIpPage(listener).isEmpty(),"open guarded auxiliary");ExitIpPageSession page=web.exitIpPage;
    check(web.current==original&&web.ports.get(original)==port&&web.owner.navigationEpoch==epoch,"chat owner port epoch unchanged");
    check(web.surface.session==page.aux&&page.aux.runtime==web.runtime&&original.active&&page.aux.active,"one surface same runtime active original");
    check(original.loads==0&&page.aux.loads==1&&ExitIpPageSession.URL.equals(page.aux.lastUrl),"load only auxiliary exact public URL");check(web.owner.reading.displayHidden&&!web.readingOwnerVisible(),"hidden chat visual work suspended");
    page.aux.navigation.onLoadError(page.aux,ExitIpPageSession.URL,new WebRequestError());page.aux.content.onCrash(page.aux);check(listener.updates==2&&web.owner.pageError.equals("original-error")&&web.owner.pending.equals("original-task"),"aux errors local; original task and errors preserved");
    check(page.aux.navigation.onLoadRequest(page.aux,new GeckoSession.NavigationDelegate.LoadRequest("https://ip123.in/zh/")).value==AllowOrDeny.ALLOW,"guarded same-origin navigation allowed");check(page.aux.navigation.onLoadRequest(page.aux,new GeckoSession.NavigationDelegate.LoadRequest("http://ip123.in/")).value==AllowOrDeny.DENY,"unsafe navigation denied");check(page.aux.navigation.onNewSession(page.aux,"https://example.com").value==null,"no external popup");
    web.owner.offline=true;check(web.closeExitIpPage(),"close remains available offline");check(web.surface.session==original&&web.current==original&&original.loads==0&&web.ports.get(original)==port&&web.owner.navigationEpoch==epoch,"return exact original with no load or navigation");
    check(web.surface.scaleX==web.readingLayout&&!web.owner.reading.displayHidden&&listener.closes==1&&!page.aux.isOpen(),"return restores existing display transform and retires auxiliary");int updates=listener.updates;page.message("late");check(listener.updates==updates&&!web.closeExitIpPage(),"retired callbacks and repeated close are inert");
    reject("network not ready",w->w.owner.networkReady=false);reject("offline",w->w.owner.offline=true);reject("connecting",w->w.owner.connecting=true);reject("guard denied",w->w.owner.guard.allowed=false);reject("native unconfirmed",w->w.nativeProtection.confirmed=false);reject("browser unconfirmed",w->w.metadata.policyAcknowledged=false);reject("route bridge missing",w->w.routePort=null);reject("environment generation changed",w->ProfileCatalog.row.put("generation",4));
    reject("unprotected direct",w->{w.owner.proxy="";w.owner.appliedIdentity=w.owner.networkIdentity();w.owner.guard.vpn=false;});
    web=fresh();web.owner.proxy="";web.owner.appliedIdentity=web.owner.networkIdentity();web.owner.guard.vpn=true;check(web.openExitIpPage(new Listener()).isEmpty(),"already admitted system VPN route allowed without fallback");web.closeExitIpPage();
    retire("connection epoch",w->w.owner.connectionEpoch++);retire("navigation epoch",w->w.owner.navigationEpoch++);retire("policy revision",w->w.identityPolicyRevision++);retire("native token",w->w.nativeProtection.token++);retire("native generation",w->w.nativeProtection.generation++);retire("route changed",w->w.owner.proxy="http://other:8888");retire("guard revoked",w->w.owner.guard.allowed=false);retire("identity changed",w->ProfileCatalog.row.put("environmentId","environment-B"));
    web=fresh();web.owner.internal=true;web.owner.appliedIdentity=web.owner.networkIdentity();NativeNetwork network=NativeNetwork.get(web.owner.context);network.verifiedRoute=new NativeNetwork.ExitRouteReceipt();listener=new Listener();check(web.openExitIpPage(listener).isEmpty(),"admitted internal route opens");page=web.exitIpPage;network.verifiedRoute=new NativeNetwork.ExitRouteReceipt();check(!page.fresh(),"replacement route receipt retires previous query");page.watch.run();check(!web.hasExitIpPage()&&web.current.loads==0,"internal route retirement never reloads chat");
    web=fresh();web.owner.internal=true;web.owner.appliedIdentity=web.owner.networkIdentity();NativeNetwork.instance=null;NativeNetwork.gets=0;
    String info=EnvironmentOverviewInfo.text(web.owner);check(info.contains("固定出口 IP：尚未核验")&&info.contains("出口地区：未取得")&&NativeNetwork.gets==0,"projection never creates a network worker and keeps unavailable explicit");
    NativeNetwork.instance=new NativeNetwork();network=NativeNetwork.instance;network.exitIp="198.51.100.8";network.lastVerified=1000;NetworkRegion.record=new JSONObject().put("ip",network.exitIp).put("region","示例地区").put("at",2000);
    info=EnvironmentOverviewInfo.text(web.owner);check(info.contains("固定出口 IP：198.51.100.8")&&info.contains("api.ipify.org")&&info.contains("核验时间："),"current fixed IP uses actual receipt source and time");check(info.contains("出口地区：上次 IP 定位 示例地区")&&info.contains("地区来源：未记录")&&info.contains("地区观测时间："),"cached IP region remains independently historical with unknown old source");
    network.admission=NetworkHealthPolicy.Admission.DEGRADED_VERIFICATION;check(EnvironmentOverviewInfo.text(web.owner).contains("固定出口 IP：上次核实"),"degraded receipt never claims fresh fixed verification");
    JSONObject pageSignal=new JSONObject().put("zone","Observed/Zone").put("language","en-US"),mainWorld=new JSONObject().put("observed",true),signals=new JSONObject().put("provenance","extension-isolated-world-fallback").put("mainWorld",mainWorld).put("parent",pageSignal),metadata=new JSONObject().put("environmentId","environment-A").put("environmentGeneration",3);
    web.owner.audit.report=new JSONObject().put("signals",signals).put("observationMetadata",metadata).put("at",3000);
    check(!EnvironmentOverviewInfo.text(web.owner).contains("Observed/Zone"),"isolated fallback cannot masquerade as page timezone");signals.put("provenance","page-main-world");mainWorld.put("observed","true");check(!EnvironmentOverviewInfo.text(web.owner).contains("Observed/Zone"),"main-world observation requires strict true");mainWorld.put("observed",true);
    info=EnvironmentOverviewInfo.text(web.owner);check(info.contains("Observed/Zone（上次网页观测）")&&info.contains("网页观测时间："),"owned old page observation carries historical label and time");web.owner.audit.current=true;check(EnvironmentOverviewInfo.text(web.owner).contains("Observed/Zone（网页观测）"),"current page observation label remains distinct");metadata.put("environmentId","environment-B");check(!EnvironmentOverviewInfo.text(web.owner).contains("Observed/Zone"),"foreign environment report not displayed");
    web=fresh();NetworkRegion.record=new JSONObject().put("ip","203.0.113.9").put("route","external:other").put("region","foreign-region");info=EnvironmentOverviewInfo.text(web.owner);check(!info.contains("203.0.113.9")&&!info.contains("foreign-region"),"other-route cached IP and region never borrowed");
    System.out.println("{\"passed\":"+checks+",\"actualAndroidExecution\":false,\"actualGeckoExecution\":false}");
  }
}
